using namespace std;

const long long MOD = 998244353;
const int MAX = 400010;
long long factArr[MAX];
long long invFactArr[MAX];

struct Triplet {
    long long g, x, y;
    Triplet(long long g, long long x, long long y) : g(g), x(x), y(y) {}
};

void computeFactorials() {
    factArr[0] = 1;
    invFactArr[0] = 1;
    for (int i = 1; i < MAX; i++) {
        factArr[i] = (factArr[i - 1] * i) % MOD;
        invFactArr[i] = (invFactArr[i - 1] * modInverse(i, MOD)) % MOD;
    }
}

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    return (factArr[n] * invFactArr[r] % MOD) * invFactArr[n - r] % MOD;
}

long long power(long long base, long long exp) {
    long long result = 1;
    long long b = base % MOD;
    long long e = exp;
    while (e > 0) {
        if (e & 1) result = (result * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return result;
}

Triplet extendedEuclid(long long a, long long b) {
    if (a == 0) return Triplet(b, 0, 1);
    Triplet res = extendedEuclid(b % a, a);
    long long x = res.y - (b / a) * res.x;
    long long y = res.x;
    return Triplet(res.g, x, y);
}

long long modInverse(long long a, long long m) {
    Triplet res = extendedEuclid(a, m);
    if (res.g != 1) return -1;
    return (res.x % m + m) % m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    computeFactorials();

    int n;
    long long k;
    cin >> n >> k;

    if (k == 0) {
        cout << factArr[n] << "\n";
        return 0;
    }
    if (n <= k) {
        cout << 0 << "\n";
        return 0;
    }

    long long ans = nCr(n, (int)k);
    int remaining = n - (int)k;
    long long totalSum = 0;

    for (int i = 0; i <= remaining; i++) {
        long long temp = nCr(remaining, i);
        temp = (temp * power(remaining - i, n)) % MOD;
        if (i & 1) {
            totalSum -= temp;
            if (totalSum < 0) totalSum += MOD;
        } else {
            totalSum += temp;
            if (totalSum >= MOD) totalSum -= MOD;
        }
    }

    long long result = (2 * ((ans * totalSum) % MOD)) % MOD;
    cout << result << "\n";

    return 0;
}

